float leaf=saturate((Color.g-max(Color.r,Color.b)*.94)*12.);
float t=saturate(Random);
float3 varied=lerp(float3(.78,.95,1.12),float3(1.13,1.04,.76),t);
float brightness=lerp(.87,1.06,t);
float3 c=Color*lerp(float3(1,1,1),varied*brightness,saturate(Variation)*leaf);
float steps=max(3.,Steps);
float3 q=floor(saturate(c)*steps+.5)/steps;
return lerp(c,q,saturate(Blend));

